const upsertSharedEvolutionUnitFile = `-- name: UpsertSharedEvolutionUnitFile :one
INSERT INTO shared_evolution_unit_file (
  workspace_id, unit_id, version_id, path, content, content_hash, mime_type, size_bytes
) VALUES (
  $1, $2, $3, $4, $5, $6, $7, $8
)
ON CONFLICT (unit_id, version_id, path) DO UPDATE SET
  content = EXCLUDED.content,
  content_hash = EXCLUDED.content_hash,
  mime_type = EXCLUDED.mime_type,
  size_bytes = EXCLUDED.size_bytes
RETURNING id, workspace_id, unit_id, version_id, path, content, content_hash, mime_type, size_bytes, created_at
`

type UpsertSharedEvolutionUnitFileParams struct {
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	UnitID      pgtype.UUID `json:"unit_id"`
	VersionID   pgtype.UUID `json:"version_id"`
	Path        string      `json:"path"`
	Content     string      `json:"content"`
	ContentHash string      `json:"content_hash"`
	MimeType    string      `json:"mime_type"`
	SizeBytes   int64       `json:"size_bytes"`
}

func (q *Queries) UpsertSharedEvolutionUnitFile(ctx context.Context, arg UpsertSharedEvolutionUnitFileParams) (SharedEvolutionUnitFile, error) {
	row := q.db.QueryRow(ctx, upsertSharedEvolutionUnitFile, arg.WorkspaceID, arg.UnitID, arg.VersionID, arg.Path, arg.Content, arg.ContentHash, arg.MimeType, arg.SizeBytes)
	var item SharedEvolutionUnitFile
	err := row.Scan(&item.ID, &item.WorkspaceID, &item.UnitID, &item.VersionID, &item.Path, &item.Content, &item.ContentHash, &item.MimeType, &item.SizeBytes, &item.CreatedAt)
	return item, err
}


